package org.transittr;

import java.io.*;import java.net.URLEncoder;import java.util.*;import org.json.*;

/** Native adaptation of otobusum-anlik's public API contracts (metkm, MIT). No OAuth secrets. */
public final class IettClient {
 private static final String API="https://otobusum.metkm.win/v1/";
 private static final LinkedHashMap<String,Info> infoCache=new LinkedHashMap<String,Info>();
 private static class Info {long at;HashSet<String> lines=new HashSet<String>();}
 private static final LinkedHashMap<String,Stops> stopCache=new LinkedHashMap<String,Stops>();
 private static class Stops {long at;ArrayList<JourneyData.Station> rows;}
 private static String text(JSONObject r,String key){return r.isNull(key)?"":r.optString(key,"").trim();}
 private static double number(JSONObject r,String key){try{return Double.parseDouble(text(r,key).replace(',','.'));}catch(Exception e){return Double.NaN;}}
 private static long time(String value){if(!value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}.*"))return 0;try{boolean iso=value.indexOf('T')>=0,zone=iso&&(value.endsWith("Z")||value.matches(".*[+-][0-9]{2}:?[0-9]{2}$"));String normalized=value.replaceAll("\\.[0-9]+(?=Z|[+-][0-9]{2}:?[0-9]{2}$)","");if(zone){if(normalized.endsWith("Z"))normalized=normalized.substring(0,normalized.length()-1)+"+0000";else normalized=normalized.replaceAll("([+-][0-9]{2}):([0-9]{2})$","$1$2");}java.text.SimpleDateFormat f=new java.text.SimpleDateFormat(iso?(zone?"yyyy-MM-dd'T'HH:mm:ssZ":"yyyy-MM-dd'T'HH:mm:ss"):"yyyy-MM-dd HH:mm:ss",Locale.US);f.setLenient(false);f.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));return f.parse(normalized).getTime();}catch(Exception e){return 0;}}
 private static String get(String path)throws IOException{String address=API+path+(path.indexOf('?')<0?"?":"&")+"city=istanbul";try{return MapHttp.text(address,null,"");}catch(IOException e){String message=String.valueOf(e.getMessage());boolean transientFailure=false;for(String status:new String[]{"500","502","503","504"})if(message.contains("HTTP "+status)||message.contains("HTTP/1.1 "+status)||message.contains("HTTP/1.0 "+status))transientFailure=true;if(!transientFailure||Thread.currentThread().isInterrupted())throw e;try{Thread.sleep(350);}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new IOException("Sorgu durduruldu");}return MapHttp.text(address,null,"");}}
 public static boolean matchesDirection(String route,String direction){return direction.length()==0||route.matches("[^_]+_"+direction+"_.*");}
 public static JourneyData.Snapshot arrivals(String json,String line)throws IOException{try{
  JSONArray rows=new JSONArray(json);if(rows.length()>500)throw new IOException("İETT durak sonuç sınırı");JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="İETT / Otobüsüm Anlık durak varışları";StringBuilder detail=new StringBuilder();
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String code=text(r,"line_code");if(line.length()>0&&!line.equalsIgnoreCase(code))continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="iett:"+text(r,"door_no");v.line=code;v.name=text(r,"line_name");v.routeCode=text(r,"route_code");v.arrivalStop=text(r,"stop_code");v.lat=number(r,"lat");v.lon=number(r,"lng");v.sourceTime=text(r,"last_location_time");v.observedAt=time(v.sourceTime);int minutes=r.isNull("minutes_left")?-1:r.optInt("minutes_left",-1);v.etaSeconds=minutes>=0&&minutes<1440?minutes*60L:-1;v.eta=v.etaSeconds>=0?minutes+" dk":"—";v.etaIsStopArrival=true;detail.append(code).append(" · ").append(v.name).append("\nDurak varışı: ").append(v.eta).append("\n");if(text(r,"door_no").length()>0)s.rows.add(v);}
  sort(s.rows);s.message=detail.length()==0?"Bu durak/hat için kaynakta şu an yaklaşan araç yok.":detail.toString();return s;
 }catch(JSONException e){throw new IOException("İETT durak varışları okunamadı");}}
 public static JourneyData.Snapshot locations(String json,String line)throws IOException{try{
  JSONObject root=new JSONObject(json);JSONArray rows=root.getJSONArray("data");if(rows.length()>500)throw new IOException("İETT araç sonuç sınırı");JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="İETT / Otobüsüm Anlık hat konumları";
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="iett:"+text(r,"bus_id");v.line=line;v.routeCode=text(r,"route_code");v.name=v.routeCode;v.closestStop=text(r,"closest_stop_code");v.lat=number(r,"lat");v.lon=number(r,"lng");v.sourceTime=text(r,"last_update_time");v.observedAt=time(v.sourceTime);v.eta="GPS";if(v.hasPosition())s.rows.add(v);}return s;
 }catch(JSONException e){throw new IOException("İETT hat konumları okunamadı");}}
 public static ArrayList<JourneyData.Station> parseStops(String json)throws IOException{try{JSONArray rows=new JSONArray(json);if(rows.length()>500)throw new IOException("İETT hat durak sınırı");ArrayList<JourneyData.Station> stops=new ArrayList<JourneyData.Station>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);double lat=number(r,"lat"),lon=number(r,"lng");if(lat<35||lat>43||lon<25||lon>45||Double.isNaN(lat)||Double.isNaN(lon))continue;JourneyData.Station stop=new JourneyData.Station(text(r,"name"),lat,lon);stop.code=text(r,"code");if(stop.code.length()>0)stops.add(stop);}return stops;}catch(JSONException e){throw new IOException("İETT hat durakları okunamadı");}}
 private static ArrayList<JourneyData.Station> stops(String line,String direction)throws IOException{String key=line+":"+direction;Stops saved;synchronized(stopCache){saved=stopCache.get(key);if(saved!=null&&System.currentTimeMillis()-saved.at<86400000)return saved.rows;}ArrayList<JourneyData.Station> rows=parseStops(get("route-stops/"+URLEncoder.encode(line,"UTF-8")+"?direction="+direction));saved=new Stops();saved.rows=rows;saved.at=System.currentTimeMillis();synchronized(stopCache){stopCache.put(key,saved);while(stopCache.size()>8)stopCache.remove(stopCache.keySet().iterator().next());}return rows;}
 public static ArrayList<JourneyData.Station> routeStops(String line,String direction)throws IOException{return stops(line,direction);}
 private static void sort(ArrayList<JourneyData.Vehicle> rows){Collections.sort(rows,new Comparator<JourneyData.Vehicle>(){public int compare(JourneyData.Vehicle a,JourneyData.Vehicle b){long x=a.etaSeconds<0?Long.MAX_VALUE:a.etaSeconds,y=b.etaSeconds<0?Long.MAX_VALUE:b.etaSeconds;return x<y?-1:x>y?1:0;}});}
 private static int serves(String stop,String line)throws IOException{Info info;synchronized(infoCache){info=infoCache.get(stop);if(info!=null&&System.currentTimeMillis()-info.at<86400000)return info.lines.contains(line)?1:0;}try{JSONObject object=new JSONObject(get("stop/"+stop));JSONArray buses=object.getJSONArray("buses");if(buses.length()>1000)throw new IOException("İETT durak hat sınırı");info=new Info();info.at=System.currentTimeMillis();for(int i=0;i<buses.length();i++)info.lines.add(buses.getString(i).toUpperCase(Locale.US));synchronized(infoCache){infoCache.put(stop,info);while(infoCache.size()>16)infoCache.remove(infoCache.keySet().iterator().next());}return info.lines.contains(line)?1:0;}catch(JSONException e){throw new IOException("İETT durak hatları okunamadı");}}
 public static JourneyData.Snapshot combine(JourneyData.Snapshot gps,JourneyData.Snapshot arrivals,String direction){JourneyData.Snapshot result=new JourneyData.Snapshot();result.source=gps.source;result.suggestedRefreshMillis=60000;result.separateMapRows=true;HashMap<String,JourneyData.Vehicle> byId=new HashMap<String,JourneyData.Vehicle>();if(arrivals!=null)for(JourneyData.Vehicle v:arrivals.rows)byId.put(v.id,v);
  for(JourneyData.Vehicle v:gps.rows){if(!matchesDirection(v.routeCode,direction))continue;JourneyData.Vehicle arrival=byId.get(v.id);if(arrival!=null&&v.line.equalsIgnoreCase(arrival.line)&&v.routeCode.length()>0&&v.routeCode.equals(arrival.routeCode)){v.eta=arrival.eta;v.etaSeconds=arrival.etaSeconds;v.etaIsStopArrival=true;v.arrivalStop=arrival.arrivalStop;}result.mapRows.add(v);}if(arrivals!=null)for(JourneyData.Vehicle v:arrivals.rows)if(matchesDirection(v.routeCode,direction))result.rows.add(v);sort(result.rows);result.message=arrivals==null?"Durak dakika servisine ulaşılamadı; hat GPS konumları gösteriliyor.":arrivals.message;return result;}
 public static JourneyData.Snapshot query(String stop,String line,String direction)throws IOException{
  line=line.toUpperCase(Locale.US);if(!stop.matches("[0-9]{1,8}")||!line.matches("[A-Za-z0-9ÇĞİÖŞÜçğıöşü-]{0,16}")||!(direction.equals("")||direction.equals("G")||direction.equals("D")))throw new IOException("Geçerli İETT durak, hat ve yön gerekli");JourneyData.Snapshot arrivals=null,gps=null;IOException failure=null;
  try{arrivals=arrivals(get("stop/"+stop+"/arrivals"),line);}catch(IOException e){failure=e;}
  if(line.length()==0){if(arrivals!=null){JourneyData.Snapshot filtered=combine(arrivals,arrivals,direction);filtered.source=arrivals.source;return filtered;}JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="İETT durak bilgisi";s.message=LiveTransit.query(1,stop)+"\nHaritada araç için hat kodu da girilebilir.";return s;}
  try{String body="<?xml version=\"1.0\" encoding=\"utf-8\"?><soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\"><soap:Body><GetHatOtoKonum_json xmlns=\"http://tempuri.org/\"><HatKodu>"+line+"</HatKodu></GetHatOtoKonum_json></soap:Body></soap:Envelope>";gps=TrackingClient.istanbul(MapHttp.text("https://api.ibb.gov.tr/iett/FiloDurum/SeferGerceklesme.asmx",body.getBytes("UTF-8"),"http://tempuri.org/GetHatOtoKonum_json"));}catch(IOException e){failure=e;}
  if(gps==null)try{gps=locations(get("bus-locations/"+URLEncoder.encode(line,"UTF-8")),line);}catch(IOException e){failure=e;}
  if(gps==null){if(arrivals!=null)gps=arrivals;else{try{JourneyData.Snapshot fallback=new JourneyData.Snapshot();fallback.source="İETT durak bilgisi";fallback.suggestedRefreshMillis=60000;fallback.message=LiveTransit.query(1,stop);return fallback;}catch(IOException e){throw failure==null?e:failure;}}}
  JourneyData.Snapshot result=combine(gps,arrivals,direction);try{result.stopServed=serves(stop,line);}catch(IOException ignored){}result.emptyMessage=result.stopServed==0?line+" bu durağa uğramıyor.":arrivals==null?"Dakika servisi alınamadı; haritada hat GPS konumları var.":"Bu durak ve yön için yaklaşan "+line+" aracı yok.";if(arrivals==null)try{result.message+="\n\n"+LiveTransit.query(1,stop);}catch(IOException ignored){}try{if(direction.length()==0){result.busStops.addAll(stops(line,"G"));HashSet<String> codes=new HashSet<String>();for(JourneyData.Station s:result.busStops)codes.add(s.code);for(JourneyData.Station s:stops(line,"D"))if(codes.add(s.code))result.busStops.add(s);}else result.busStops.addAll(stops(line,direction));}catch(IOException e){result.message+="\nHat durakları şu an alınamadı; araç konumları korunuyor.";}
  return result;
 }
}
